   474  /**
   475   * Determines the center point in spherical coordinates of a cell given by
   476   * a FaceIJK address at a specified resolution.
   477   *
   478   * @param h The FaceIJK address of the cell.
   479   * @param res The H3 resolution of the cell.
   480   * @param g The spherical coordinates of the cell center point.
   481   */
   482  void _faceIjkToGeo(const FaceIJK *h, int res, LatLng *g) {
   483      Vec2d v;
   484      _ijkToHex2d(&h->coord, &v);
   485      _hex2dToGeo(&v, h->face, res, 0, g);
   486  }
