   488  /**
   489   * Generates the cell boundary in spherical coordinates for a pentagonal cell
   490   * given by a FaceIJK address at a specified resolution.
   491   *
   492   * @param h The FaceIJK address of the pentagonal cell.
   493   * @param res The H3 resolution of the cell.
   494   * @param start The first topological vertex to return.
   495   * @param length The number of topological vertexes to return.
   496   * @param g The spherical coordinates of the cell boundary.
   497   */
   498  void _faceIjkPentToCellBoundary(const FaceIJK *h, int res, int start,
   499                                  int length, CellBoundary *g) {
   500      int adjRes = res;
   501      FaceIJK centerIJK = *h;
   502      FaceIJK fijkVerts[NUM_PENT_VERTS];
   503      _faceIjkPentToVerts(&centerIJK, &adjRes, fijkVerts);
   504
   505      // If we're returning the entire loop, we need one more iteration in case
   506      // of a distortion vertex on the last edge
   507      int additionalIteration = length == NUM_PENT_VERTS ? 1 : 0;
   508
   509      // convert each vertex to lat/lng
   510      // adjust the face of each vertex as appropriate and introduce
   511      // edge-crossing vertices as needed
   512      g->numVerts = 0;
   513      FaceIJK lastFijk;
   514      for (int vert = start; vert < start + length + additionalIteration;
   515           vert++) {
   516          int v = vert % NUM_PENT_VERTS;
   517
   518          FaceIJK fijk = fijkVerts[v];
   519
   520          _adjustPentVertOverage(&fijk, adjRes);
   521
   522          // all Class III pentagon edges cross icosa edges
   523          // note that Class II pentagons have vertices on the edge,
   524          // not edge intersections
   525          if (isResolutionClassIII(res) && vert > start) {
   526              // find hex2d of the two vertexes on the last face
   527
   528              FaceIJK tmpFijk = fijk;
   529
   530              Vec2d orig2d0;
   531              _ijkToHex2d(&lastFijk.coord, &orig2d0);
   532
   533              int currentToLastDir = adjacentFaceDir[tmpFijk.face][lastFijk.face];
   534
   535              const FaceOrientIJK *fijkOrient =
   536                  &faceNeighbors[tmpFijk.face][currentToLastDir];
   537
   538              tmpFijk.face = fijkOrient->face;
   539              CoordIJK *ijk = &tmpFijk.coord;
   540
   541              // rotate and translate for adjacent face
   542              for (int i = 0; i < fijkOrient->ccwRot60; i++) _ijkRotate60ccw(ijk);
   543
   544              CoordIJK transVec = fijkOrient->translate;
   545              _ijkScale(&transVec, unitScaleByCIIres[adjRes] * 3);
   546              _ijkAdd(ijk, &transVec, ijk);
   547              _ijkNormalize(ijk);
   548
   549              Vec2d orig2d1;
   550              _ijkToHex2d(ijk, &orig2d1);
   551
   552              // find the appropriate icosa face edge vertexes
   553              int maxDim = maxDimByCIIres[adjRes];
   554              Vec2d v0 = {3.0 * maxDim, 0.0};
   555              Vec2d v1 = {-1.5 * maxDim, 3.0 * M_SQRT3_2 * maxDim};
   556              Vec2d v2 = {-1.5 * maxDim, -3.0 * M_SQRT3_2 * maxDim};
   557
   558              Vec2d *edge0;
   559              Vec2d *edge1;
   560              switch (adjacentFaceDir[tmpFijk.face][fijk.face]) {
   561                  case IJ:
   562                      edge0 = &v0;
   563                      edge1 = &v1;
   564                      break;
   565                  case JK:
   566                      edge0 = &v1;
   567                      edge1 = &v2;
   568                      break;
   569                  case KI:
   570                  default:
   571                      assert(adjacentFaceDir[tmpFijk.face][fijk.face] == KI);
   572                      edge0 = &v2;
   573                      edge1 = &v0;
   574                      break;
   575              }
   576
   577              // find the intersection and add the lat/lng point to the result
   578              Vec2d inter;
   579              _v2dIntersect(&orig2d0, &orig2d1, edge0, edge1, &inter);
   580              _hex2dToGeo(&inter, tmpFijk.face, adjRes, 1,
   581                          &g->verts[g->numVerts]);
   582              g->numVerts++;
   583          }
   584
   585          // convert vertex to lat/lng and add to the result
   586          // vert == start + NUM_PENT_VERTS is only used to test for possible
   587          // intersection on last edge
   588          if (vert < start + NUM_PENT_VERTS) {
   589              Vec2d vec;
   590              _ijkToHex2d(&fijk.coord, &vec);
   591              _hex2dToGeo(&vec, fijk.face, adjRes, 1, &g->verts[g->numVerts]);
   592              g->numVerts++;
   593          }
   594
   595          lastFijk = fijk;
   596      }
   597  }
